import SwiftUI

/// Semantic colors from design/tokens.json (asset catalog, generated by
/// design/generate_apple_assets.py). Never use system colors in the features.
extension Color {
    /// Text and icons of a warning (design token "warning"), readable in light and dark
    /// mode. Always next to an icon or words, never the only cue.
    static let warning = Color("Warning")
    /// Text and icons of a success ("success"), always next to an icon or words.
    static let success = Color("Success")
    /// Text and icons of an error ("error"), always next to an icon or words.
    static let error = Color("Error")
    /// Fill of a secondary swipe action, under white text ("action").
    static let action = Color("Action")
    /// Fill of a swipe action that takes a bottle out ("destructive").
    static let destructive = Color("Destructive")
    /// Fill of a neutral action, or of a bottle whose wine has no style ("neutral").
    static let neutral = Color("Neutral")
    /// Small symbols on an accent or warning fill ("on-tint").
    static let onTint = Color("OnTint")
    /// Text on a light wine color ("ink-on-light"), and on a dark one ("ink-on-dark").
    static let inkOnLight = Color("InkOnLight")
    static let inkOnDark = Color("InkOnDark")
}
